w=np.load('d_w.npy'); b=float(np.load('d_b.npy')[0])
def isbad(a):
    r=np.zeros(len(a),bool)
    for i in mem: r|=np.asarray(model.in_basin(i,a)).astype(bool)
    return r
ct=torch.tensor(c); wt=torch.tensor(w)
def run(dv, kr, thr):
    x=torch.tensor(xi); nf=torch.zeros(len(x))
    with torch.no_grad():
        for k in range(20):
