import numpy as np, torch, model
net=model.load(); mem=[0,5,10,12,14]
c=np.load('an_c.npy')[:4096]; xi=np.load('an_xi.npy')[:4096]; bad=np.load('an_bad.npy')[:4096]
w=np.load('d_w.npy'); b=float(np.load('d_b.npy')[0])
def isbad(a):
    r=np.zeros(len(a),bool)
    for i in mem: r|=np.asarray(model.in_basin(i,a)).astype(bool)
    return r
ct=torch.tensor(c); wt=torch.tensor(w)
def run(dv, kr, thr):
    x=torch.tensor(xi)
    with torch.no_grad():
        for k in range(20):
            t=torch.full((len(x),),1-k/20)
            v,acts=net.velocity(x,t,ct,capture=("out_act",))
            if kr[0]<=k<kr[1]:
                m=(acts["out_act"]@wt+b>thr).float()
                v=v+m[:,None]*torch.tensor(dv,dtype=torch.float32)
            x=x-v/20
    return x.numpy()
a0=run([0,0],(0,0),0)
print('base',bad.mean())
for kr in [(8,11),(6,11)]:
  for thr in [0.0]:
    for ang in range(0,360,45):
      for s in [4,8]:
        dv=[s*np.cos(np.radians(ang)), s*np.sin(np.radians(ang))]
        a=run(dv,kr,thr)
        nb=isbad(a); mv=np.linalg.norm(a-a0,axis=1)>0.3
        print(kr,thr,ang,s,'bad',nb.mean().round(4),'goodmoved',(mv&~bad).mean().round(4),'badrescued',(~nb&bad).mean().round(4), flush=True)
